-- KÜR (nicht im Abitur)
CREATE TABLE Klasse (
  KlasseNr    INTEGER PRIMARY KEY,
  Bezeichnung TEXT NOT NULL
);
CREATE TABLE Schueler (
  SchuelerNr INTEGER PRIMARY KEY,
  Name       TEXT NOT NULL,
  KlasseNr   INTEGER,
  FOREIGN KEY (KlasseNr) REFERENCES Klasse(KlasseNr)
);
INSERT INTO Klasse VALUES (1, '12a');
INSERT INTO Schueler VALUES (100, 'Mika R.', 3);   -- Fehler: Klasse 3 gibt es nicht

SELECT k.Bezeichnung, s.Name                        -- Ausblick: auch Klassen ohne Schüler
FROM Klasse k LEFT JOIN Schueler s ON k.KlasseNr = s.KlasseNr;

