loesung.sql:
CREATE TABLE Fall (
  FallNr   INTEGER PRIMARY KEY,
  Titel    TEXT,
  LeiterNr INTEGER NOT NULL,
  FOREIGN KEY (LeiterNr) REFERENCES Ermittler(ErmittlerNr)
);
INSERT INTO Fall VALUES (10, 'Das Phantom', 1);
SELECT *
FROM Fall;

SELECT f.Titel, e.Name
FROM Fall f JOIN Ermittler e ON f.LeiterNr = e.ErmittlerNr
WHERE f.Status = 'offen';

SELECT p.Vorname, p.Nachname
FROM Person p LEFT JOIN verdaechtig v ON p.PersonNr = v.PersonNr
WHERE v.FallNr IS NULL;

CREATE TABLE Schueler (
  SchuelerNr INTEGER PRIMARY KEY,
  Name       TEXT NOT NULL,
  Klasse     TEXT
);
CREATE TABLE AG (
  AGNr  INTEGER PRIMARY KEY,
  Titel TEXT NOT NULL,
  Raum  TEXT
);
CREATE TABLE nimmtTeil (
  SchuelerNr INTEGER,
  AGNr       INTEGER,
  Seit       TEXT,
  PRIMARY KEY (SchuelerNr, AGNr),
  FOREIGN KEY (SchuelerNr) REFERENCES Schueler(SchuelerNr),
  FOREIGN KEY (AGNr) REFERENCES AG(AGNr)
);
INSERT INTO Schueler VALUES (1, 'Mika R.', '12a');
INSERT INTO Schueler VALUES (2, 'Lena K.', '12b');
INSERT INTO Schueler VALUES (3, 'Noa T.', '12a');
INSERT INTO AG VALUES (1, 'Robotik', 'B204');
INSERT INTO AG VALUES (2, 'Schulgarten', 'Garten');
INSERT INTO nimmtTeil VALUES (1, 1, '2026-09-01');
INSERT INTO nimmtTeil VALUES (1, 2, '2026-09-15');
INSERT INTO nimmtTeil VALUES (2, 1, '2026-09-01');
INSERT INTO nimmtTeil VALUES (3, 2, '2026-10-01');
SELECT a.Titel, COUNT(*) AS Teilnehmende
FROM AG a, nimmtTeil n
WHERE a.AGNr = n.AGNr
GROUP BY a.AGNr, a.Titel
ORDER BY Teilnehmende DESC;
